INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Kunden- und Marktperspektive > Aftersales
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Aftersales ein wichtiger Bestandteil der Kundenzufriedenheit?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert langfristige Kundenbindung"}, {"text": "Nein", "correct": false, "because": "Aftersales ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Aftersales-Dienstleistungen ohne Rückmeldung der Kunden verbessert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenfeedback ist essenziell für Optimierung"}, {"text": "Ja", "correct": false, "because": "Ohne Feedback spekulativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Aftersales-Maßnahmen immer kostenpflichtig sein?', 2, '[{"text": "Nein", "correct": true, "because": "Kostenloser Service kann Kundenbindung fördern"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend kostenpflichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Aftersales die Lebensdauer eines IT-Produkts verlängern?', 2, '[{"text": "Ja", "correct": true, "because": "Wartung und Support erhöhen Nutzungsdauer"}, {"text": "Nein", "correct": false, "because": "Aftersales wirkt positiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Aftersales nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Unternehmensgrößen"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei Aftersales am wichtigsten?', 3, '[{"text": "Kundensupport", "correct": true, "because": "Sichert Zufriedenheit und Problemlösung"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt Aftersales primär?', 2, '[{"text": "Kundenbindung", "correct": true, "because": "Fördert langfristige Beziehungen"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aftersales-Maßnahme erhöht die Produktzuverlässigkeit?', 2, '[{"text": "Wartungsservice", "correct": true, "because": "Verhindert Ausfälle"}, {"text": "Rabattaktion", "correct": false, "because": "Verkaufsförderung"}, {"text": "Produktwerbung", "correct": false, "because": "Marketing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Kundenzufriedenheit im Aftersales-Bereich?', 3, '[{"text": "Reaktionszeit", "correct": true, "because": "Schnelle Hilfe steigert Zufriedenheit"}, {"text": "Produktgröße", "correct": false, "because": "Physisch"}, {"text": "Lieferantenname", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil eines guten Aftersales-Services?', 2, '[{"text": "Kundentreue", "correct": true, "because": "Stärkt langfristige Beziehungen"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Produkteinführung", "correct": false, "because": "Unabhängig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aftersales-Maßnahmen fördern die Kundenzufriedenheit?', 4, '[{"text": "Technischer Support", "correct": true, "because": "Löst Probleme"}, {"text": "Wartungsservice", "correct": true, "because": "Sichert Funktion"}, {"text": "Garantieleistungen", "correct": true, "because": "Schafft Vertrauen"}, {"text": "Produktwerbung", "correct": false, "because": "Marketing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effektivität von Aftersales?', 3, '[{"text": "Reaktionszeit", "correct": true, "because": "Schnelligkeit zählt"}, {"text": "Servicequalität", "correct": true, "because": "Bestimmt Zufriedenheit"}, {"text": "Verfügbarkeit", "correct": true, "because": "Erreichbarkeit wichtig"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein guter Aftersales-Service?', 3, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Erhöht Akzeptanz"}, {"text": "Kundenbindung", "correct": true, "because": "Fördert Treue"}, {"text": "Wiederholungskäufe", "correct": true, "because": "Steigert Umsatz"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei schlechtem Aftersales auftreten?', 4, '[{"text": "Kundenunzufriedenheit", "correct": true, "because": "Mangelnder Support"}, {"text": "Reputationsverlust", "correct": true, "because": "Vertrauen schwindet"}, {"text": "Höhere Reklamationen", "correct": true, "because": "Fehlende Lösungen"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für einen effektiven Aftersales-Service wichtig?', 3, '[{"text": "Kompetenter Support", "correct": true, "because": "Löst Probleme"}, {"text": "Schnelle Reaktion", "correct": true, "because": "Zeit ist entscheidend"}, {"text": "Garantieleistungen", "correct": true, "because": "Sichert Qualität"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Aftersales fördert die Kundenbindung. b) Kundenfeedback ist für Aftersales unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bindung ja, Feedback wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wartungsservice verlängert die Produktlebensdauer. b) Aftersales muss immer kostenpflichtig sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung ja, Kosten optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schnelle Reaktionszeiten steigern die Kundenzufriedenheit. b) Aftersales ist nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reaktion ja, für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Garantieleistungen sind Teil des Aftersales. b) Schlechter Aftersales hat keine Auswirkungen auf die Reputation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Garantie ja, Reputation leidet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aftersales kann Wiederholungskäufe fördern. b) Technischer Support ist im Aftersales unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Käufe ja, Support wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

